const plans={30:12000,90:30000,180:54000};
let selected=30,pass=null;
const checkout=document.querySelector('#checkout'),wallet=document.querySelector('#wallet');
const won=n=>'₩'+n.toLocaleString('ko-KR');
function selectPlan(days){if(!Object.hasOwn(plans,days))throw new Error('지원하지 않는 이용 기간입니다.');selected=Number(days);document.querySelector('#order-plan').textContent=selected+'일 이용권';document.querySelector('#order-price').textContent=won(plans[selected]);if(wallet.open)wallet.close();if(!checkout.open)checkout.showModal();return {days:selected,price:plans[selected],demo:true};}
document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>selectPlan(Number(b.dataset.plan))));
document.querySelectorAll('.close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
function showWallet(){const box=document.querySelector('#wallet-content');if(!pass){box.innerHTML='<div class="pass-info"><h3>아직 선택한 이용권이 없어요.</h3><p>요금제를 선택하고 데모 결제를 완료하면 이용권 화면을 확인할 수 있습니다.</p></div><button class="primary full" id="choose-pass">요금제 살펴보기 ↗</button>';box.querySelector('button').onclick=()=>{wallet.close();document.querySelector('#plans').scrollIntoView();};}else{box.innerHTML='<div class="pass-info"><span class="pill">데모 이용권 · 실제 연결 불가</span><h3>'+pass.days+'일 이용권</h3><p>예시 이용 종료일: '+pass.expires+'</p><p>결제 금액 예시: '+won(plans[pass.days])+'</p><code class="key">DEMO-OUTLINE-KEY-NOT-FOR-CONNECTION</code><button class="outline full" id="copy-key">데모 키 복사 <span>⧉</span></button></div><p class="fine">화면 확인용 키입니다. 새로고침하면 데모 이용권이 초기화됩니다.</p><div class="wallet-actions"><a class="button primary" href="https://getoutline.org/get-started/" target="_blank" rel="noopener">앱 설치 안내 ↗</a><button class="outline" id="extend">연장 화면 보기</button></div>';box.querySelector('#copy-key').onclick=async()=>{try{await navigator.clipboard.writeText('DEMO-OUTLINE-KEY-NOT-FOR-CONNECTION');notify('데모 키를 복사했습니다. 실제 연결에는 사용할 수 없습니다.');}catch{notify('복사할 수 없습니다. 표시된 데모 키를 직접 선택해 주세요.');}};box.querySelector('#extend').onclick=()=>selectPlan(pass.days);}if(!wallet.open)wallet.showModal();}
document.querySelector('#account').onclick=showWallet;
document.querySelector('#order-form').addEventListener('submit',e=>{e.preventDefault();const end=new Date();end.setDate(end.getDate()+selected);pass={days:selected,expires:end.toLocaleDateString('ko-KR')};checkout.close();e.target.reset();showWallet();});
let toastTimer;function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4000);}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'preview_vpn_plan',description:'선택한 기간의 데모 주문 화면을 엽니다. 결제나 키 발급은 수행하지 않습니다.',inputSchema:{type:'object',properties:{days:{type:'integer',enum:[30,90,180]}},required:['days'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.days))throw new Error('days는 정수여야 합니다.');return selectPlan(input.days);}})).catch(()=>{});}catch{}}
